import math, re
from collections import Counter

def entropy(s):
    """Shannon entropy in bits per character."""
    n = len(s)
    return sum(c / n * math.log2(n / c) for c in Counter(s).values())

# (pattern, minimum entropy for the captured value)
RULES = {
    "aws-access-key-id": (re.compile(r"\b((?:AKIA|ASIA)[A-Z0-9]{16})\b"), 0.0),
    "generic-secret": (re.compile(
        r"(?i)(?:password|secret|token)\s*=\s*\"([^\"]{8,})\""), 3.5),
}

lines = [
    'aws_key = "AKIAIOSFODNN7EXAMPLE"',
    'password = "changeme123"',
    'token = "q7Vx2LpZ9sKd4TfR1mWc8YbN"',
    'secret = "aaaaaaaaaaaaaaaa"',
]

for no, line in enumerate(lines, 1):
    for rule, (rx, min_h) in RULES.items():
        for m in rx.finditer(line):
            value, h = m.group(1), entropy(m.group(1))
            verdict = "FLAG" if h >= min_h else "skip"
            print(f"line {no}: {verdict} {rule:<17} H={h:.2f} {value}")

