import json, os
from cryptography.exceptions import InvalidTag
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

kek = AESGCM.generate_key(bit_length=256)

def aad(context):                     # canonical bytes of the context
    return json.dumps(context, sort_keys=True).encode()

def encrypt(plaintext, context):
    n = os.urandom(12)
    return n + AESGCM(kek).encrypt(n, plaintext, aad(context))

def decrypt(blob, context):
    return AESGCM(kek).decrypt(blob[:12], blob[12:], aad(context))

alice_dek = encrypt(b"alice's data key", {"tenant": "alice"})

print(decrypt(alice_dek, {"tenant": "alice"}))
try:
    # Mallory copies Alice's wrapped key into their own row
    decrypt(alice_dek, {"tenant": "mallory"})
except InvalidTag:
    print("wrong context: InvalidTag")

# Output:
# b"alice's data key"
# wrong context: InvalidTag
